def lesson_for_day(day: int) -> Lesson:
    if not 1 <= day <= 28:
        raise ValueError("학습 일자는 1~28 사이여야 합니다.")
    title, goal, concept, confusion, review = TOPICS[day - 1]
    example = concept.split(". ")[1] if ". " in concept else concept
    market_link = f"미국 시장 적용: {title}을 볼 때 최신 원자료와 시장 기대를 함께 확인하고, 이 요인이 기업 현금흐름·할인율·위험 중 어디에 작용하는지 연결해 보세요."
    quiz = (f"{title}의 핵심 개념으로 맞는 것은?\nA) {concept}\nB) {confusion}\nC) 관련 데이터 없이 주가 방향을 확정한다\nD) 한 가지 지표만으로 기업가치를 판단한다", "관련 뉴스가 시장에 미칠 수 있는 반대 방향 또는 한계는 무엇인가요?", "오늘 개념을 실제 미국 시장 사례에 적용할 때 확인할 자료 한 가지는 무엇인가요?")
    answers = ("A — " + concept, confusion, review)
    return Lesson(day, title, goal, concept, example, market_link, confusion, quiz, answers, review)


def all_lessons() -> list[Lesson]:
    return [lesson_for_day(day) for day in range(1, 29)]
